from math import *
import numpy as np
from static_parameters import *
from physics import *

#valid_cols = ["height", "velocity", "acceleration", "thrust"]

valid_cols = {"height": "Height (m)",
              "velocity": "Velocity (m/s)",
              "acceleration": "Acceleration (m/s^2)",
              "thrust": "Thrust (N)",
              "max_height": "Maximum reached altitude (m)"
              }


# SimulationResult class is used to store the data generated by simulation.

@dataclass
class SimulationResult:
    def __init__(self, quantities: list = []):
        self.time = np.array([])
        for q in quantities:
            self.addQuantity(q)

    def addQuantity(self, name: str):
        setattr(self, name, np.array([]))

    def addValues(self, quantity: str, values: list):
        quantity_attribute = getattr(self, quantity)
        result = np.concatenate((quantity_attribute, values))
        setattr(self, quantity, result)

@dataclass
class OptimizationResult(SimulationResult):
    def __init__(self):
        super().__init__()


class Simulation:
    def __init__(self, rocket: Rocket, environment: Environment, initial_state: list | None = None):
        self.rocket = rocket
        self.environment = environment
        if initial_state == None:
            self.initial_state = np.array([0.0, 0.0, rocket.initial_air_volume])
        else:
            self.initial_state = initial_state

        self.water_phase = WaterPhase(self.rocket, self.environment)
        self.air_phase = AirPhase(self.rocket, self.environment)
        self.ballistic_phase = BallisticPhase(self.rocket, self.environment)


    def createInitialAirState(self, previous_result):
        air_temperature = (self.environment.temperature * 
                (self.rocket.initial_air_volume / self.rocket.tank_volume)**(self.environment.air_adiabatic_constant - 1))
        
        tank_pressure = self.water_phase.tankPressure(previous_result[2][-1])

        air_mass = tank_pressure * self.rocket.tank_volume / (self.environment.air_gas_constant * air_temperature)

        return np.array([previous_result[0][-1], previous_result[1][-1], air_temperature, air_mass])



    def run(self, cols: list = ["height"]):

        quantities = [col for col in cols if col in valid_cols]

        result = SimulationResult()


        water_result = self.water_phase.run(self.initial_state, initial_time=0.0)

        initial_air_state = self.createInitialAirState(water_result.y)
        initial_air_time = water_result.t[-1]
        air_result = self.air_phase.run(initial_air_state, initial_air_time)

        initial_ballistic_state = np.array([air_result.y[0][-1], air_result.y[1][-1]])
        ballistic_result = self.ballistic_phase.run(initial_ballistic_state, air_result.t[-1])


        result.addValues("time", np.concatenate((water_result.t, air_result.t, ballistic_result.t)))

        if "height" in quantities:
            result.addQuantity("height")
            result.addValues("height", np.concatenate((water_result.y[0], air_result.y[0], ballistic_result.y[0])))

        if "velocity" in quantities:
            result.addQuantity("velocity")
            result.addValues("velocity", np.concatenate((water_result.y[1], air_result.y[1], ballistic_result.y[1])))

        if "thrust" in quantities:
            water_thrust = np.array([self.water_phase.thrust(air_volume) for air_volume in water_result.y[2]])
            air_thrust = np.array([self.air_phase.thrust(air_mass, air_temperature) for air_mass, air_temperature in zip(air_result.y[3], air_result.y[2])])
            ballistic_thrust = np.zeros_like(ballistic_result.t)

            result.addQuantity("thrust")
            result.addValues("thrust", np.concatenate((water_thrust, air_thrust, ballistic_thrust)))

        return result


        

